(() => {
 const {sources,topics}=REGULATION_DATA,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let active='architecture',jurisdiction='pra',mode='comparator';
 const sourceCard=(key,entry,compact=false)=>{const s=sources[key];return `${compact?'<article class="compare-card">':'<div>'}<header class="source-head"><div><h3>${esc(s.name)}</h3><p>${esc(s.title)}</p></div><span class="status">${esc(s.status)}</span></header><div class="source-body"><section><h4>SOURCE REFERENCE</h4><a class="reference-link" href="${s.url}#page=${entry.page}" target="_blank" rel="noopener">${esc(entry.ref)} <span>↗</span></a><p class="reference-page">PDF page ${entry.page} · open the complete provision</p></section><section><h4>PLAIN-LANGUAGE INTERPRETATION</h4><p>${esc(entry.interpretation)}</p></section><section><h4>CALCULATION IMPLICATION</h4><p>${esc(entry.implication)}</p></section></div>${compact?'</article>':'</div>'}`};
 function filtered(){const q=$('topic-search').value.trim().toLowerCase();return q?topics.filter(t=>(t.name+' '+t.keywords+' '+t.question+' '+t.group).toLowerCase().includes(q)):topics;}
 function options(){const list=filtered();$('topic').innerHTML=list.map(t=>`<option value="${t.id}" ${t.id===active?'selected':''}>${esc(t.group)} · ${esc(t.name)}</option>`).join('');if(!list.some(t=>t.id===active)&&list.length)active=list[0].id;$('topic').value=active;return list;}
 function render(push=true){const list=options(),topic=topics.find(t=>t.id===active)||list[0];if(!topic){$('navigator-card').innerHTML='<div class="empty">No matching topic. Try “ES”, “index” or “curvature”.</div>';return;}
  $('topic-group').textContent=topic.group;$('topic-name').textContent=topic.name;$('topic-question').textContent=topic.question;$('navigator-card').innerHTML=sourceCard(jurisdiction,topic.entries[jurisdiction]);$('compare-name').textContent=topic.name;$('comparison-grid').innerHTML=['pra','us','basel'].map(k=>sourceCard(k,topic.entries[k],true)).join('');
  $('comparison-summary').textContent=summary(topic);$('related-topics').innerHTML=topics.filter(t=>t.group===topic.group&&t.id!==topic.id).map(t=>`<button data-topic="${t.id}">${esc(t.name)}</button>`).join('')||topics.filter(t=>t.id!==topic.id).slice(0,4).map(t=>`<button data-topic="${t.id}">${esc(t.name)}</button>`).join('');
  document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{active=b.dataset.topic;$('topic-search').value='';render();scrollTo({top:$('navigator').offsetTop-20,behavior:'smooth'})});
  if(push)history.replaceState(null,'',`#${mode}/${jurisdiction}/${active}`);window.gtag?.('event','regulation_topic_view',{topic:active,jurisdiction,tool:mode});
 }
 function summary(t){if(t.id==='rfet'||t.id==='nmrf')return 'The largest conceptual difference is the US proposal’s type A / type B NMRF split. Reclassify factors and rebuild the capital flow before comparing totals.';if(t.id==='governance')return 'Start with legal status: PRA is final UK text, the US NPR is proposed, and Basel is a minimum standard implemented locally. Then check permissions and effective dates.';if(['girr','csr','equity-fx-commodity','sbm'].includes(t.id))return 'Keep raw validated sensitivities fixed, then apply each jurisdiction’s factor definitions, buckets, weights and correlations. A capital difference may be calibration rather than economics.';return 'Build a common inventory of trades, factors and data first. Apply each source’s definitions and calculations separately, and reconcile the result at intermediate steps rather than comparing only the final charge.';}
 function tab(next){mode=next;const nav=next==='navigator';$('navigator').hidden=!nav;$('comparator').hidden=nav;$('navigator-tab').setAttribute('aria-selected',nav);$('comparator-tab').setAttribute('aria-selected',!nav);render();}
 $('topic').onchange=e=>{active=e.target.value;render()};$('jurisdiction').onchange=e=>{jurisdiction=e.target.value;render()};$('topic-search').oninput=()=>{options();if(filtered().length){active=filtered()[0].id;render()}};$('navigator-tab').onclick=()=>tab('navigator');$('comparator-tab').onclick=()=>tab('comparator');
 const hash=location.hash.slice(1).split('/');if(['navigator','comparator'].includes(hash[0]))mode=hash[0];if(sources[hash[1]])jurisdiction=hash[1];if(topics.some(t=>t.id===hash[2]))active=hash[2];$('jurisdiction').value=jurisdiction;tab(mode);
 window.REGULATION_APP={select({topic,jurisdiction:source,mode:tool}){if(topic&&!topics.some(t=>t.id===topic))throw Error('Unknown topic');if(source&&!sources[source])throw Error('Unknown jurisdiction');if(tool&&!['navigator','comparator'].includes(tool))throw Error('Unknown tool');if(topic)$("topic-search").value="";active=topic||active;jurisdiction=source||jurisdiction;$('jurisdiction').value=jurisdiction;tab(tool||mode);return {topic:active,jurisdiction,mode}}};
})();
